<script lang="ts">
import { tick } from 'svelte';
import type { ApexConfig, ApexLocale } from '../../../core/src/apex/mod.ts';
import type { ApexStore } from '../../../state/src/stores/apex.svelte.ts';
import AccountDashboard from './account/AccountDashboard.svelte';
import DemoMailbox from './account/DemoMailbox.svelte';
import { useResolver } from './url.ts';
let {config,locale,store,route}:{config:ApexConfig;locale:ApexLocale;store:ApexStore;route:string}=$props();
const resolve = useResolver();
let mode=$state<'login'|'register'>('login');
let name=$state('');
let email=$state('');
let password=$state('');
let consent=$state(false);
let revealPassword=$state(false);
let recoveryCompleted=$state(false);
let submitButton=$state<HTMLButtonElement>();
let recovery=$derived(route.includes('recuperar')||store.recoveryMode);
let canAuthenticate=$derived(store.isDemo||store.authConfigured);
let adventure=$derived(config.experiences.find(item=>item.kind==='adventure'));
const ui=(es:string,en:string)=>locale==='es'?es:en;
$effect(()=>{store.user?.id;store.accountMode;password='';name='';email='';consent=false;mode='login';revealPassword=false;});
function switchForm(value:'login'|'register'){mode=value;store.clearFeedback();password='';consent=false;recoveryCompleted=false;if(store.isDemo){email=store.demoCredentials?.email??'';name=value==='register'?(store.demoProfile?.name??''):'';}}
async function chooseAccount(value:'demo'|'live'){await store.chooseAccountMode(value);password='';email=value==='demo'?(store.demoCredentials?.email??''):'';name='';consent=false;recoveryCompleted=false;revealPassword=false;}
async function useExample(){await store.chooseAccountMode('demo');mode='login';email=store.demoCredentials?.email??'';password=store.demoCredentials?.password??'';store.clearFeedback();await tick();submitButton?.focus();}
async function fillRegistration(){await store.chooseAccountMode('demo');mode='register';name=store.demoProfile?.name??'';email=store.demoCredentials?.email??'';password=store.demoCredentials?.password??'';store.clearFeedback();await tick();submitButton?.focus();}
async function submit(event:SubmitEvent){event.preventDefault();if(!canAuthenticate||store.busy)return;store.clearFeedback();if(recovery){if(store.recoveryMode){await store.updatePassword(password);if(!store.error){recoveryCompleted=true;password='';}}else await store.recover(email);}else if(mode==='register'){if(!consent)return;await store.signUp(name,email,password);}else await store.signIn(email,password);}
</script>
{#if store.isDemo&&store.demoPersistenceWarning}<div class="wrap"><p class="account-feedback" role="status">{store.demoPersistenceWarning}</p></div>{/if}
{#if store.user&&!recovery&&!recoveryCompleted}
<AccountDashboard {config} {locale} {store}/>
{:else}
<section class="account-entry wrap" class:account-entry-recovery={recovery}>
 <div class="account-entry-story"><div class="account-entry-story-photo"><img src={config.account?.heroImage ?? config.brand.aboutImage ?? config.brand.background} alt=""/><div></div></div><div class="account-entry-story-content"><p class="account-kicker">{store.isDemo?ui('TU UNIVERSO APEX · DEMOSTRACIÓN','YOUR APEX UNIVERSE · DEMONSTRATION'):ui('TU UNIVERSO APEX','YOUR APEX UNIVERSE')}</p><h1>{recovery?ui('Vuelve a tu próxima historia.','Return to your next story.'):ui('Tu próxima aventura, en un solo lugar.','Your next adventure, all in one place.')}</h1><p>{ui('Lo que imaginas. Lo que estás planeando. Los momentos que ya son tuyos. Todo empieza aquí.','What you imagine. What you’re planning. The moments that are already yours. It all starts here.')}</p><div class="account-entry-benefits"><div><span>01</span><p>{ui('Dale forma a tu próxima salida','Shape your next outing')}</p></div><div><span>02</span><p>{ui('Encuentra cada detalle de tu experiencia','Find every detail of your experience')}</p></div><div><span>03</span><p>{ui('Vuelve a tus mejores momentos','Return to your favorite moments')}</p></div></div><a class="account-entry-back" href={resolve('/#experiencias')}>← {ui('Seguir explorando','Keep exploring')}</a></div><div class="account-entry-photo-label"><span>{adventure?.title[locale] ?? 'APEX EXPERIENCE'}</span><p>{ui('Lo de siempre puede esperar.','The everyday can wait.')}</p></div></div>
 <div class="account-entry-panel"><div class="account-entry-card">
  <div class="account-entry-card-top"><p class="account-kicker">{ui('ÁREA PERSONAL','PERSONAL AREA')}</p>{#if store.isDemo}<span class="account-demo-chip"><span></span>{ui('Demostración','Demonstration')}</span>{/if}</div>
  {#if store.demoAvailable&&(store.authConfigured||!store.isDemo)}<div class="account-mode-picker" role="group" aria-label={ui('Elegir tipo de cuenta','Choose account type')}><button type="button" class:active={store.isDemo} aria-pressed={store.isDemo} onclick={()=>chooseAccount('demo')}>{ui('Cuenta de ejemplo','Example account')}</button>{#if store.authConfigured}<button type="button" class:active={!store.isDemo} aria-pressed={!store.isDemo} onclick={()=>chooseAccount('live')}>{ui('Mi cuenta APEX','My APEX account')}</button>{/if}</div>{/if}
  {#if recoveryCompleted}<div class="account-auth-complete"><span class="account-auth-success" aria-hidden="true">✓</span><h2>{store.isDemo?ui('Recorrido completado.','Journey completed.'):ui('Ya puedes volver.','You can return now.')}</h2><p>{store.isDemo?ui('Probaste el restablecimiento de acceso sin enviar correos ni guardar contraseñas. La cuenta pública de ejemplo conserva sus credenciales originales.','You tried access recovery without sending emails or storing passwords. The public example account keeps its original credentials.'):ui('Tu contraseña se actualizó. Vuelve a iniciar sesión para continuar.','Your password was updated. Sign in again to continue.')}</p>{#if store.isDemo&&store.demoCredentials}<div class="account-credential-summary"><span>{store.demoCredentials.email}</span><code>{store.demoCredentials.password}</code></div>{/if}<a class="button" href={resolve('/cuenta/')} onclick={()=>{recoveryCompleted=false;mode='login';}}>{store.user?ui('Ir a mi cuenta','Go to my account'):ui('Volver a iniciar sesión','Back to sign in')} ↗</a></div>
  {:else if store.isDemo&&store.demoConfirmationRequired}
   <div class="account-auth-pending"><span class="account-auth-mail" aria-hidden="true">✉</span><h2>{ui('Un paso más.','One more step.')}</h2><p>{ui('Tu cuenta de ejemplo está lista para activarse. Abre la vista previa de confirmación de abajo para completar el recorrido.','Your example account is ready to activate. Open the confirmation preview below to complete the journey.')}</p><span class="account-pending-address">{store.demoPendingEmail}</span><p class="account-detail-note">{ui('Todo ocurre en este navegador. No se envió ningún correo.','Everything happens in this browser. No email was sent.')}</p></div><DemoMailbox {store} {locale}/>
  {:else}
   <h2>{recovery?(store.recoveryMode?ui('Un nuevo comienzo.','A fresh start.'):ui('Recupera tu acceso.','Recover your access.')):mode==='register'?ui('Empieza tu historia.','Start your story.'):ui('Qué bueno verte.','Good to see you.')}</h2><p class="account-auth-subtitle">{recovery?(store.recoveryMode?ui('Elige una contraseña para completar el recorrido.','Choose a password to complete the journey.'):ui('Te acompañamos para volver a tu cuenta.','We’ll help you return to your account.')):mode==='register'?ui('Crea tu espacio para planear, guardar y vivir.','Create your space to plan, save and experience.'):ui('Entra y descubre lo que viene para ti.','Sign in and discover what comes next for you.')}</p>
   {#if !recovery}<div class="auth-tabs account-auth-tabs"><button type="button" class:active={mode==='login'} onclick={()=>switchForm('login')}>{ui('Ingresar','Sign in')}</button><button type="button" class:active={mode==='register'} onclick={()=>switchForm('register')}>{ui('Crear cuenta','Create account')}</button></div>{/if}
   {#if store.isDemo}<div class="account-demo-intro"><span class="account-demo-spark" aria-hidden="true">✦</span><div><strong>{ui('Una cuenta para explorar.','An account to explore.')}</strong><p>{ui('Datos ficticios, guardados solo en este navegador. No se envían correos ni se crean reservas reales.','Fictional data, stored only in this browser. No emails are sent or real bookings created.')}</p></div></div>{#if store.demoCredentials&&!store.recoveryMode}<div class="account-example-credentials"><div><span>{ui('CORREO DE EJEMPLO','EXAMPLE EMAIL')}</span><code>{store.demoCredentials.email}</code></div><div><span>{ui('CONTRASEÑA PÚBLICA DE EJEMPLO','PUBLIC EXAMPLE PASSWORD')}</span><code>{store.demoCredentials.password}</code></div>{#if mode==='login'&&!recovery}<button type="button" onclick={useExample}>{ui('Usar cuenta de ejemplo','Use example account')} <span>↗</span></button>{:else if mode==='register'&&!recovery}<button type="button" onclick={fillRegistration}>{ui('Usar datos de ejemplo','Use example details')} <span>↗</span></button>{/if}</div>{/if}{/if}
   {#if !canAuthenticate}<p class="account-feedback">{ui('El acceso por cuenta no está disponible por ahora. Puedes seguir explorando y preparar una consulta.','Account access is unavailable right now. You can keep exploring and prepare an inquiry.')}</p>{/if}
   {#if store.isDemo&&mode==='register'&&!recovery}<p class="account-form-hint account-register-hint">{ui('El registro recorre el perfil ficticio mostrado. Usa los datos de ejemplo para probar su activación.','Registration walks through the fictional profile shown. Use the example details to try its activation.')}</p>{/if}<form class="account-auth-form" onsubmit={submit}>
    {#if !recovery&&mode==='register'}<label for="account-name">{store.isDemo?ui('Nombre de ejemplo','Example name'):ui('Nombre','Name')}<input id="account-name" autocomplete={store.isDemo?'off':'name'} placeholder={store.demoProfile?.name??ui('Tu nombre','Your name')} bind:value={name} minlength="2" maxlength="120" required readonly={store.isDemo} disabled={!canAuthenticate}/></label>{/if}
    {#if !store.recoveryMode}<label for="account-email">{store.isDemo?ui('Correo de ejemplo','Example email'):ui('Correo electrónico','Email address')}<input id="account-email" type="email" autocomplete={store.isDemo?'off':'email'} placeholder={store.isDemo?(store.demoCredentials?.email??''):ui('tu@correo.com','you@email.com')} bind:value={email} required readonly={store.isDemo&&mode==='register'} disabled={!canAuthenticate}/></label>{/if}
    {#if !recovery||store.recoveryMode}<label for="account-password">{store.isDemo?ui(store.recoveryMode?'Nueva contraseña de ejemplo':'Contraseña de ejemplo',store.recoveryMode?'New example password':'Example password'):ui(store.recoveryMode?'Nueva contraseña':'Contraseña',store.recoveryMode?'New password':'Password')}<span class="account-password-field"><input id="account-password" type={revealPassword?'text':'password'} autocomplete={store.isDemo?'off':mode==='login'&&!store.recoveryMode?'current-password':'new-password'} placeholder={store.isDemo?ui('Usa solo una contraseña ficticia','Use only a fictional password'):ui('Tu contraseña','Your password')} bind:value={password} minlength={mode==='register'||store.recoveryMode?8:1} required disabled={!canAuthenticate}/><button type="button" aria-label={revealPassword?ui('Ocultar contraseña','Hide password'):ui('Mostrar contraseña','Show password')} aria-pressed={revealPassword} onclick={()=>revealPassword=!revealPassword}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>{#if revealPassword}<path d="m3 3 18 18"/>{/if}</svg></button></span></label>{/if}
    {#if store.isDemo&&store.recoveryMode}<p class="account-form-hint">{ui('Esta acción es una simulación. No uses una contraseña personal: no se guardará y la clave pública de ejemplo seguirá funcionando.','This action is a simulation. Do not use a personal password: it will not be stored and the public example password will continue to work.')}</p>{/if}
    {#if mode==='register'&&!recovery}<label class="checkbox account-auth-consent"><input type="checkbox" bind:checked={consent} required disabled={!canAuthenticate}/><span>{ui('He leído el','I have read the')} <a href={resolve('/privacidad/')} target="_blank" rel="noopener noreferrer">{ui('aviso de privacidad','privacy notice')}</a>.</span></label>{/if}
    <button bind:this={submitButton} class="button account-auth-submit" type="submit" disabled={!canAuthenticate||store.busy}>{#if store.busy}<span class="account-mini-loader"></span>{ui('Un momento…','One moment…')}{:else}{recovery?(store.recoveryMode?ui('Completar restablecimiento','Complete reset'):ui('Preparar recuperación','Prepare recovery')):mode==='register'?(store.isDemo?ui('Crear cuenta de ejemplo','Create example account'):ui('Crear mi cuenta','Create my account')):ui('Entrar a mi universo APEX','Enter my APEX universe')} <span>↗</span>{/if}</button>
   </form>
   <div class="account-auth-meta">{#if recovery}<a href={resolve('/cuenta/')}>← {ui('Volver a iniciar sesión','Back to sign in')}</a>{:else}<span>{ui('¿Olvidaste tu contraseña?','Forgot your password?')}</span><a href={resolve('/cuenta/recuperar/')} onclick={()=>{store.clearFeedback();email=store.isDemo?(store.demoCredentials?.email??''):email;}}>{ui('Recuperar acceso','Recover access')}</a>{/if}</div>
   {#if store.isDemo&&recovery&&!store.recoveryMode}<DemoMailbox {store} {locale}/>{/if}
  {/if}
  {#if store.error}<p class="account-feedback error" role="alert">{store.error}</p>{/if}{#if store.message}<p class="account-feedback" role="status">{store.message}</p>{/if}
  <div class="account-entry-signature"><span>APEX</span><p>{ui('Hecho para vivirlo.','Made to be experienced.')}</p></div>
 </div></div>
</section>
{/if}
{#if !store.user&&store.guestInquiries.length}<section class="wrap apex-local-drafts"><p class="eyebrow">{ui('SOLO EN ESTE NAVEGADOR','ONLY IN THIS BROWSER')}</p><h2>{ui('Tus borradores locales.','Your local drafts.')}</h2><p class="muted">{ui('No se han enviado a APEX, no están vinculados a una cuenta y no confirman reservas.','Not sent to APEX, not linked to an account and not confirmed reservations.')}</p><div class="apex-draft-grid">{#each store.guestInquiries as draft}<article class="brand-panel"><span class="pill">{ui('Borrador local','Local draft')}</span><h3>{config.experiences.find(item=>item.id===draft.experienceId)?.title[locale]??draft.experienceId}</h3><p>{draft.date} · {draft.people} {ui('personas','people')}</p><button class="link-button" onclick={()=>store.removeGuestDraft(draft.id)}>{ui('Eliminar borrador de este navegador','Remove draft from this browser')}</button></article>{/each}</div></section>{/if}
